def f(xs, queries):
    out=[]
    for q in queries:
        if q in xs:
            out.append(q)
    return out

def f(xs):
    out=[]
    for x in xs:
        if x not in out:
            out.append(x)
    return out

def f(start):
    queue=[start]
    while queue:
        node=queue.pop(0)
    return node

def fib(n):
    if n < 2: return n
    return fib(n-1)+fib(n-2)

def f(parts):
    result=''
    for part in parts:
        result += part
    return result
